    "totalDonations": 5,
    "note": "আমি শুধু শুক্রবার রক্ত/ প্লাটিলেট দিতে পারব, কারণ অন্যান্য দিন গুলো আমার চাকরি আছে। চাইলে সব সময় ছুটি নিতে পারব না। যাঁরা রক্তের জন্য ডোনার খুঁজেন কল দেন আগে লাস্ট ডোনেট তারিখ দেখে নিবেন প্লিজ। রক্তদান সময় হওয়ার আগে অযথা কেউ কল দিয়ে বিরক্ত করবেন না প্লিজ। রক্তদানের সময় হলে নিচে লেখা থাকবে রক্তদানের সময় হয়েছে।",
