    "suspendedReason": null,
    "totalDonations": 5,
    "note": "আমি সুস্থ ও সক্ষম থাকলে যেকোনো দিন রক্ত দিতে প্রস্তুত। কারও প্রয়োজনে আমার রক্ত যদি কাজে লাগে—এটাই আমার সবচেয়ে বড় আনন্দ। প্রয়োজন হলে নির্দ্বিধায় যোগাযোগ করবেন, সাহায্যের জন্য আমি সবসময় পাশে আছি। একটা বিষয় স্পষ্ট করে বলছি—আমি রক্তের জন্য আপনাদের কাছ থেকে ১ টাকাও নেব না, আর আমাকে যেন কোনওভাবেই বাধ্য করা বা চাপ দেওয়া না হয়। আমি নিজের ইচ্ছাতেই সবাইকে সম্পূর্ণ ফ্রি রক্ত দিতে চাই।",
